import java.time.DayOfWeek;
import java.time.LocalDate;

public class Billing {
    public static LocalDate dueDate(LocalDate issued) {
        return nextBusinessDay(issued.plusDays(30));
    }

    static LocalDate nextBusinessDay(LocalDate d) {
        if (d.getDayOfWeek() == DayOfWeek.SATURDAY) {
            return d.plusDays(2);
        } else if (d.getDayOfWeek() == DayOfWeek.SUNDAY) {
            return d.plusDays(1);
        }
        return d;
    }
}

